"""Pack twelve wide saga illustrations as four-level flash artwork."""
from pathlib import Path
from PIL import Image, ImageChops

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "assets_local/quest/redesign/saga-covers"


def build():
    lines = ["#pragma once", "#include <FreeInkUI.h>", "#include <algorithm>",
             "// Generated by tools_local/quest/build_saga_covers.py.", "namespace questcover {"]
    for n in range(12):
        image = Image.open(SOURCE / f"cover-{n}-source.png").convert("RGB")
        bounds = ImageChops.difference(image, Image.new("RGB", image.size, "white")).convert("L").point(lambda px: 255 if px > 35 else 0).getbbox()
        assert bounds
        image = image.crop(bounds)
        image.thumbnail((168, 104), Image.Resampling.LANCZOS)
        canvas = Image.new("RGB", (176, 112), "white")
        canvas.paste(image, ((176-image.width)//2, 108-image.height))
        canvas.save(SOURCE / f"cover-{n}.png")
        pixels = list(canvas.convert("L").tobytes())
        coverage = [(255-value+42)//85 for value in pixels]
        data = [sum(coverage[at+k] << (6-2*k) for k in range(4)) for at in range(0,len(coverage),4)]
        lines.append(f"inline constexpr uint8_t cover{n}[] = {{")
        for at in range(0,len(data),24): lines.append("    "+", ".join(f"0x{value:02x}" for value in data[at:at+24])+",")
        lines.append("};")
    lines.append("inline constexpr const uint8_t* COVERS[] = {"+", ".join(f"cover{n}" for n in range(12))+"};")
    lines.append('''inline void draw(freeink::ui::DrawTarget& target, freeink::ui::Rect area, unsigned index) {
  namespace fui = freeink::ui;
  if (index >= 12 || area.empty()) return;
  const int width = std::min(int(area.width), int(area.height) * 176 / 112), height = width * 112 / 176;
  if (!width || !height) return;
  const int left = area.x + (area.width - width) / 2, top = area.y + (area.height - height) / 2;
  static constexpr fui::Paint PAINTS[] = {fui::Paint::solid(fui::Color::White), fui::Paint::dither(fui::Color::LightGray),
                                         fui::Paint::dither(fui::Color::DarkGray), fui::Paint::solid(fui::Color::Black)};
  for (int y = 0; y < height; ++y) {
    const int row = y * 112 / height * 44;
    int start = 0, previous = -1;
    for (int x = 0; x <= width; ++x) {
      const int sourceX = x < width ? x * 176 / width : 0;
      const int value = x < width ? (COVERS[index][row + sourceX / 4] >> (6 - sourceX % 4 * 2)) & 3 : -1;
      if (value != previous) {
        if (previous > 0) target.fill(fui::makeRect(left + start, top + y, x - start, 1), PAINTS[previous]);
        start = x; previous = value;
      }
    }
  }
}
}  // namespace questcover''')
    (ROOT / "src/apps_local/quest/QuestSagaCovers.h").write_text("\n".join(lines)+"\n","utf-8")
    print("Saga covers: twelve 176x112 four-level illustrations, 59,136 flash bytes, no heap allocation")


if __name__ == "__main__":
    build()
